import { test, expect } from '@playwright/test';

test.describe('API Response Caching', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should cache API responses and load dashboard instantly on repeat visits', async ({ page }) => {
    // First visit: intercept API call and wait for response
    await page.route('**/api/dashboard/data', (route) => {
      route.continue();
    });

    // Verify initial load
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    const dataContainer = page.getByTestId('data-container');
    await expect(dataContainer).toBeVisible();

    // Verify data is loaded
    const dataItem = page.getByText('Data loaded successfully');
    await expect(dataItem).toBeVisible();

    // Second visit: clear cache and reload page
    await page.route('**/api/dashboard/data', (route) => {
      route.abort('failed');
    });

    await page.reload();

    // Verify cached data is displayed instantly
    await expect(dataItem).toBeVisible();
    await expect(dataContainer).toBeVisible();

    // Verify no loading spinner is visible
    const loadingSpinner = page.getByTestId('loading-spinner');
    await expect(loadingSpinner).not.toBeVisible();
  });

  test('should display cache unavailable message when API is down', async ({ page }) => {
    // Intercept API call and abort it
    await page.route('**/api/dashboard/data', (route) => {
      route.abort('failed');
    });

    // Verify initial load attempt
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Verify cache unavailable message is displayed
    const cacheUnavailableMessage = page.getByText('Cache unavailable');
    await expect(cacheUnavailableMessage).toBeVisible();

    // Verify fallback UI is shown
    const fallbackData = page.getByText('Fallback data');
    await expect(fallbackData).toBeVisible();

    // Verify no loading spinner is visible
    const loadingSpinner = page.getByTestId('loading-spinner');
    await expect(loadingSpinner).not.toBeVisible();
  });
});
